=Label each of the following data items. For each item, provide a label and a confidence score (0.0 to 1.0).

Label categories: {{ $json.body.labels ? $json.body.labels.join(', ') : 'positive, negative, neutral' }}

Data items:
{{ JSON.stringify($json.body.items || $json.body.data || [], null, 2) }}

Return JSON array:
[{"index": 0, "text": "original text", "label": "...", "confidence": 0.95, "reasoning": "brief reason"}]

parameters.jsCode:
const items = $input.all();
const content = items[0].json.message.content;
const confidenceThreshold = $('Webhook').item.json.body.confidenceThreshold || 0.8;

let labeled;
try {
  const jsonMatch = content.match(/\[.*\]/s);
  labeled = jsonMatch ? JSON.parse(jsonMatch[0]) : [];
} catch (e) {
  labeled = [];
}

const highConfidence = labeled.filter(l => l.confidence >= confidenceThreshold);
const lowConfidence = labeled.filter(l => l.confidence < confidenceThreshold);

// Label distribution
const distribution = {};
for (const item of labeled) {
  distribution[item.label] = (distribution[item.label] || 0) + 1;
}

return [{
  json: {
    totalItems: labeled.length,
    highConfidenceCount: highConfidence.length,
    lowConfidenceCount: lowConfidence.length,
    confidenceThreshold,
    avgConfidence: labeled.length > 0 ? parseFloat((labeled.reduce((s, l) => s + l.confidence, 0) / labeled.length).toFixed(3)) : 0,
    labelDistribution: distribution,
    highConfidenceLabels: highConfidence,
    lowConfidenceLabels: lowConfidence,
    needsReview: lowConfidence.map(l => ({ index: l.index, text: l.text, suggestedLabel: l.label, confidence: l.confidence, reasoning: l.reasoning }))
  }
}];
